const raw = $input.first().json;
const upd = raw.body || raw;
const chatId = '7988990790';
const m = upd.message || upd.edited_message;
if (!m || String(m.chat.id) !== chatId) return [{ json: { hasMessage: false } }];
const text = (m.text || '').trim();
if (!text) return [{ json: { hasMessage: false } }];
const t = text.toLowerCase();
const WB = "https://webhookn8n6.inovareinteligenciaartificial.com/webhook/";
const has = (...k) => k.some(x => t.includes(x));

const CONFIRM = has('confirmar','confirmo','pode sim','executar agora','manda ver','autorizo');

// === ACOES DESTRUTIVAS (exigem confirmacao) ===
const ACTIONS = [
  { k:['reiniciar','restart','desfibrilador','reinicia'], path:'tool-restart-servico', method:'POST', label:'reiniciar um servico' },
  { k:['deploy','publicar deploy','lancar deploy'],        path:'tool-deploy-trigger',  method:'POST', label:'disparar um deploy' },
  { k:['faxina','limpar vps','faxina pesada'],             path:'tool-limpar-vps-v2',   method:'POST', label:'fazer faxina pesada na VPS' },
  { k:['vacuum','doutor do banco'],                        path:'tool-vacuum-db',       method:'POST', label:'rodar vacuum no banco' },
  { k:['backup','salva tudo','salvar tudo'],               path:'tool-backup-agora-v2', method:'POST', label:'fazer backup' },
];
for (const a of ACTIONS) {
  if (has(...a.k)) {
    if (CONFIRM) return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:a.path, toolUrl:WB+a.path, toolMethod:a.method, toolBody:'{}' } }];
    return [{ json:{ hasMessage:true, text:text+'\n\n[ATENCAO: usuario quer '+a.label+'. NAO execute. Peca para ele responder "confirmar" antes.]', chatId, intent:'chat', toolMethod:'none' } }];
  }
}

// === VIDEO: gerar video historia (PRODUCAO v3 - assincrono) ===
if (has('gerar video','gera video','criar video','cria video','fazer video','produzir video','video de historia','video historia')) {
  const tema = text.replace(/^.*?(gerar?|criar?|fazer|produzir)\s*(um\s*)?video\s*(de\s*historia)?\s*/i,'').trim() || 'Uma historia motivacional curta';
  const body = JSON.stringify({titulo:tema, format:'short', cenas:[{texto:tema, image_prompt:'Cinematic scene: '+tema}]});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool_async', toolName:'gera-video-historia', toolUrl:WB+'gera-video-historia', toolMethod:'POST', toolBody:body } }];
}

// === VIDEO: gerar video IA (Veo Flow) ===
if (has('veo','video ia','video ai','gerar clipe','clipe ia','gerar cena')) {
  const prompt = text.replace(/^.*?(veo|video ia|video ai|gerar clipe|clipe ia|gerar cena)\s*/i,'').trim() || 'A cinematic slow-motion scene of nature';
  const body = JSON.stringify({prompt, aspect:'9:16'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'veo-flow-gerar', toolUrl:WB+'veo-flow-gerar', toolMethod:'POST', toolBody:body } }];
}

// === VIDEO: checar status ===
if (has('status video','status do video','como ta o video','video pronto','progresso video')) {
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'status-video', toolUrl:WB+'status-video', toolMethod:'GET', toolBody:'{}' } }];
}

// === ROTEIRO: gerar roteiro com IA ===
if (has('roteiro','criar roteiro','gerar roteiro','escrever roteiro','script')) {
  const tema = text.replace(/^.*?(roteiro|script|escrever)\s*(sobre|de|para)?\s*/i,'').trim() || 'historia motivacional curta';
  const body = JSON.stringify({tema, formato:'short', duracao:'60s'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-roteiro', toolUrl:WB+'gerar-roteiro', toolMethod:'POST', toolBody:body } }];
}

// === TRADUZIR: traduzir conteudo ===
if (has('traduzir','translate','traducao','traduz')) {
  const langMatch = t.match(/(?:para|to|em)\s*(ingles|english|en|espanhol|spanish|es|frances|french|fr|japones|japanese|ja)/);
  const idioma = langMatch ? langMatch[1].substring(0,2) : 'en';
  const texto = text.replace(/^.*?(traduzir|translate|traducao)\s*(para|to|em)?\s*(ingles|english|espanhol|spanish|frances|french|japones|japanese)?\s*/i,'').trim();
  if (!texto) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o texto que deseja traduzir.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({texto, idioma});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'traduzir-conteudo', toolUrl:WB+'traduzir-conteudo', toolMethod:'POST', toolBody:body } }];
}

// === NARRACAO: script otimizado pra TTS ===
if (has('narracao','narrar','script narracao','script de narracao','narracao para')) {
  const roteiro = text.replace(/^.*?(narracao|narrar|script)\s*(de narracao|narracao|para)?\s*/i,'').trim();
  if (!roteiro || roteiro.length < 10) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o roteiro pra converter em script de narracao.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({roteiro});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-narracao', toolUrl:WB+'gerar-narracao', toolMethod:'POST', toolBody:body } }];
}

// === LEGENDAS: gerar SRT ===
if (has('legenda','legendar','gerar legenda','srt','subtitle')) {
  const texto = text.replace(/^.*?(legenda|legendar|srt|subtitle)\s*(para|de|do)?\s*/i,'').trim();
  if (!texto || texto.length < 10) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o texto completo para gerar legendas.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({texto, duracao:60});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-legendas', toolUrl:WB+'gerar-legendas', toolMethod:'POST', toolBody:body } }];
}

// === RESUMIDOR: resumir texto longo pra short ===
if (has('resumir','resumo','encurtar texto','sintetizar','resume isso')) {
  const texto = text.replace(/^.*?(resumir|resumo|encurtar|sintetizar|resume)\s*(de|isso|esse|este)?\s*/i,'').trim();
  if (!texto || texto.length < 20) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o texto longo que deseja resumir.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({texto, formato:'short'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'resumir-conteudo', toolUrl:WB+'resumir-conteudo', toolMethod:'POST', toolBody:body } }];
}

// === IDEIAS: gerar ideias de conteudo ===
if (has('ideias','sugerir video','sugerir conteudo','ideias de conteudo','ideias para','me da ideias')) {
  const nicho = text.replace(/^.*?(ideias?|sugerir)\s*(de|para|video|conteudo)?\s*/i,'').trim() || 'manhwa recap';
  const body = JSON.stringify({nicho, quantidade:10, formato:'shorts'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-ideias', toolUrl:WB+'gerar-ideias', toolMethod:'POST', toolBody:body } }];
}

// === HOOKS: gerar ganchos virais ===
if (has('hook','hooks','gancho','ganchos','ganchos para','hook para')) {
  const tema = text.replace(/^.*?(hook|gancho)s?\s*(para|de|sobre)?\s*/i,'').trim() || 'video viral';
  const body = JSON.stringify({tema, quantidade:10});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-hooks', toolUrl:WB+'gerar-hooks', toolMethod:'POST', toolBody:body } }];
}

// === NICHO: analisar nicho ===
if (has('analisar nicho','analise do nicho','analise nicho','estudar nicho')) {
  const nicho = text.replace(/^.*?(analisar|analise|estudar)\s*(do|de)?\s*nicho\s*/i,'').trim() || 'shorts de curiosidades';
  const body = JSON.stringify({nicho});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'analisar-nicho', toolUrl:WB+'analisar-nicho', toolMethod:'POST', toolBody:body } }];
}

// === REVISAR VIDEO: qualidade via ffprobe ===
if (has('revisar video','qualidade do video','qualidade video','checar video','verificar video')) {
  const urlMatch = text.match(/https?:\/\/[^\s]+/);
  const videoUrl = urlMatch ? urlMatch[0] : '';
  if (!videoUrl) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie a URL do video pra eu revisar a qualidade.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({video_url:videoUrl});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'revisar-video', toolUrl:WB+'revisar-video', toolMethod:'POST', toolBody:body } }];
}

// === RESPOSTAS: gerar resposta pra comentario ===
if (has('responder comentario','resposta para','resposta comentario','reply para')) {
  const comentario = text.replace(/^.*?(responder|resposta)\s*(para|comentario|ao)?\s*/i,'').trim();
  if (!comentario) return [{ json:{ hasMessage:true, text:text+'\n\n[Cole o comentario que deseja responder.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({comentario});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-resposta-comentario', toolUrl:WB+'gerar-resposta-comentario', toolMethod:'POST', toolBody:body } }];
}

// === COMMUNITY POST: gerar post pra aba comunidade ===
if (has('community post','post comunidade','enquete','enquete para','post engajamento')) {
  const tema = text.replace(/^.*?(community|comunidade|enquete|post)\s*(post|para|de|sobre)?\s*/i,'').trim() || 'manhwa/anime';
  const tipo = has('enquete') ? 'enquete' : has('teaser') ? 'teaser' : has('meme') ? 'meme' : 'enquete';
  const body = JSON.stringify({tipo, tema});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-community-post', toolUrl:WB+'gerar-community-post', toolMethod:'POST', toolBody:body } }];
}

// === ANALISAR TITULO: avaliar e melhorar titulo ===
if (has('analisar titulo','avaliar titulo','melhorar titulo','titulo bom','nota do titulo')) {
  const titulo = text.replace(/^.*?(analisar|avaliar|melhorar|nota)\s*(do|de)?\s*titulo\s*/i,'').trim();
  if (!titulo) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o titulo que deseja analisar.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({titulo});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'analisar-titulo', toolUrl:WB+'analisar-titulo', toolMethod:'POST', toolBody:body } }];
}

// === CTA: gerar call to action ===
if (has('cta','call to action','gerar cta','criar cta')) {
  const contexto = text.replace(/^.*?(cta|call to action|gerar cta)\s*(para|de|do)?\s*/i,'').trim() || 'video de entretenimento';
  const body = JSON.stringify({contexto});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-cta', toolUrl:WB+'gerar-cta', toolMethod:'POST', toolBody:body } }];
}

// === BIO CANAL: gerar descricao do canal ===
if (has('bio do canal','bio canal','descricao do canal','about do canal')) {
  const canal = text.replace(/^.*?(bio|descricao|about)\s*(do|de)?\s*canal\s*/i,'').trim() || 'InovareManhwaVerse';
  const body = JSON.stringify({canal, nicho:'manhwa/anime recap'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-bio-canal', toolUrl:WB+'gerar-bio-canal', toolMethod:'POST', toolBody:body } }];
}

// === REESCREVER: melhorar texto/copy ===
if (has('reescrever','melhorar texto','rewrite','melhorar copy','reescreva')) {
  const texto = text.replace(/^.*?(reescrever|melhorar|rewrite|reescreva)\s*(texto|copy|isso)?\s*/i,'').trim();
  if (!texto || texto.length < 5) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o texto que deseja melhorar.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({texto});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'reescrever-texto', toolUrl:WB+'reescrever-texto', toolMethod:'POST', toolBody:body } }];
}

// === EMAIL: gerar email marketing ===
if (has('email marketing','gerar email','criar email','email para')) {
  const produto = text.replace(/^.*?(email|gerar email|criar email)\s*(marketing|para|de|do)?\s*/i,'').trim() || 'canal YouTube';
  const body = JSON.stringify({produto});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-email', toolUrl:WB+'gerar-email', toolMethod:'POST', toolBody:body } }];
}

// === MONETIZACAO: consultor de renda ===
if (has('monetizar','monetizacao','como ganhar dinheiro','ganhar dinheiro','renda do canal')) {
  const canal = text.replace(/^.*?(monetizar|monetizacao|ganhar dinheiro|renda)\s*(do|de|no|com)?\s*(canal)?\s*/i,'').trim() || 'canal anime/manhwa';
  const body = JSON.stringify({canal});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'consultar-monetizacao', toolUrl:WB+'consultar-monetizacao', toolMethod:'POST', toolBody:body } }];
}

// === HASHTAGS: trending tags ===
if (has('hashtag','hashtags','trending tags','tags trending')) {
  const nicho = text.replace(/^.*?(hashtag|trending)s?\s*(para|de|do)?\s*/i,'').trim() || 'entretenimento';
  const body = JSON.stringify({nicho, plataforma:'youtube'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-hashtags', toolUrl:WB+'gerar-hashtags', toolMethod:'POST', toolBody:body } }];
}

// === PERSONA: criar persona do canal ===
if (has('criar persona','persona do canal','persona','avatar do canal')) {
  const nicho = text.replace(/^.*?(criar|persona|avatar)\s*(do|de)?\s*(canal|persona)?\s*/i,'').trim() || 'manhwa/anime';
  const body = JSON.stringify({nicho});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'criar-persona', toolUrl:WB+'criar-persona', toolMethod:'POST', toolBody:body } }];
}

// === THUMBNAIL AB: comparar 2 opcoes ===
if (has('thumbnail ab','comparar thumbnail','ab test thumbnail','ab thumbnail')) {
  const tema = text.replace(/^.*?(thumbnail|comparar|ab)\s*(ab|test|thumbnail)?\s*/i,'').trim() || 'video epico';
  const body = JSON.stringify({tema});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'thumbnail-ab', toolUrl:WB+'thumbnail-ab', toolMethod:'POST', toolBody:body } }];
}

// === INTRO: abertura do video ===
if (has('intro','criar intro','abertura','intro para','gerar intro')) {
  const tema = text.replace(/^.*?(intro|abertura|gerar intro)\s*(para|de|do)?\s*/i,'').trim() || 'video viral';
  const body = JSON.stringify({tema, duracao:'30s'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-intro', toolUrl:WB+'gerar-intro', toolMethod:'POST', toolBody:body } }];
}

// === MENTOR: conselho de crescimento ===
if (has('mentor','me ajuda com','conselho sobre','como crescer','dica de crescimento','estou travado')) {
  const situacao = text.replace(/^.*?(mentor|me ajuda|conselho|como crescer|dica|travado)\s*(com|sobre|de|no)?\s*/i,'').trim();
  if (!situacao) return [{ json:{ hasMessage:true, text:text+'\n\n[Descreva sua situacao ou duvida sobre o canal.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({situacao});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'mentor-crescimento', toolUrl:WB+'mentor-crescimento', toolMethod:'POST', toolBody:body } }];
}

// === POSTS SOCIAL: gerar posts cross-platform ===
if (has('post twitter','post threads','post linkedin','criar post sobre','post social','posts para')) {
  const plataforma = has('twitter') ? 'twitter' : has('threads') ? 'threads' : has('linkedin') ? 'linkedin' : 'twitter';
  const conteudo = text.replace(/^.*?(post|posts|criar post)\s*(twitter|threads|linkedin|social|para|sobre)?\s*/i,'').trim() || 'conteudo do canal';
  const body = JSON.stringify({conteudo, plataforma});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-posts-social', toolUrl:WB+'gerar-posts-social', toolMethod:'POST', toolBody:body } }];
}

// === STORYBOARD: plano visual do video ===
if (has('storyboard','criar storyboard','storyboard para','plano visual')) {
  const roteiro = text.replace(/^.*?(storyboard|plano visual)\s*(para|de|do)?\s*/i,'').trim();
  if (!roteiro || roteiro.length < 10) return [{ json:{ hasMessage:true, text:text+'\n\n[Envie o roteiro ou tema pra criar o storyboard.]', chatId, intent:'chat', toolMethod:'none' } }];
  const body = JSON.stringify({roteiro});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-storyboard', toolUrl:WB+'gerar-storyboard', toolMethod:'POST', toolBody:body } }];
}

// === CONCORRENCIA: analisar competidores ===
if (has('concorrencia','concorrentes','analisar concorrentes','quem compete','competidores')) {
  const nicho = text.replace(/^.*?(concorrencia|concorrentes|competidores|compete)\s*(comigo|no|de|do)?\s*/i,'').trim() || 'anime/manhwa';
  const body = JSON.stringify({nicho});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'analisar-concorrencia', toolUrl:WB+'analisar-concorrencia', toolMethod:'POST', toolBody:body } }];
}

// === END SCREEN: tela final do video ===
if (has('end screen','tela final','encerramento','final do video')) {
  const tema = text.replace(/^.*?(end screen|tela final|encerramento|final)\s*(do video|para|de)?\s*/i,'').trim() || 'video entretenimento';
  const body = JSON.stringify({tema});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-endscreen', toolUrl:WB+'gerar-endscreen', toolMethod:'POST', toolBody:body } }];
}

// === INTRO: abertura do video ===
if (has('intro','criar intro','abertura','intro para','gerar intro')) {
  const tema = text.replace(/^.*?(intro|abertura|gerar intro)\s*(para|de|do)?\s*/i,'').trim() || 'video viral';
  const body = JSON.stringify({tema, duracao:'30s'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-intro', toolUrl:WB+'gerar-intro', toolMethod:'POST', toolBody:body } }];
}

// === DASHBOARD: listar tools ===
if (has('dashboard','listar tools','todas as tools','ajuda hermes','o que voce faz','help tools')) {
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'hermes-dashboard', toolUrl:WB+'hermes-dashboard', toolMethod:'GET', toolBody:'{}' } }];
}

// === TENDENCIAS: o que ta bombando ===
if (has('tendencia','tendencias','trending','o que ta bombando','o que esta em alta')) {
  const nicho = text.replace(/^.*?(tendencia|trending|bombando|em alta)s?\s*(de|para|no|em)?\s*/i,'').trim() || 'entretenimento/anime';
  const body = JSON.stringify({nicho});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'detectar-tendencias', toolUrl:WB+'detectar-tendencias', toolMethod:'POST', toolBody:body } }];
}

// === SERIE: planejar serie de videos ===
if (has('criar serie','planejar serie','serie de video','serie sobre')) {
  const tema = text.replace(/^.*?(criar|planejar|serie)\s*(de video|sobre|de)?\s*/i,'').trim() || 'jornada do heroi';
  const body = JSON.stringify({tema, episodios:10});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'criar-serie', toolUrl:WB+'criar-serie', toolMethod:'POST', toolBody:body } }];
}

// === PINNED: comentario fixado ===
if (has('pinned comment','pinned','comentario fixado','fixar comentario')) {
  const tema = text.replace(/^.*?(pinned|fixar|fixado|comment)\s*(comment|comentario|para|de)?\s*/i,'').trim() || 'video entretenimento';
