}

// === PERFORMANCE: avaliar metricas ===
if (has('avaliar performance','minhas metricas','performance do canal','diagnostico do canal','como estao')) {
  const body = JSON.stringify({nicho:'anime/manhwa'});
  return [{ json:{ hasMessage:true, text:text+'\n\n[Envie suas metricas: views, inscritos, CTR, retencao. Se nao tiver, vou analisar com estimativas.]', chatId, intent:'tool', toolName:'avaliar-performance', toolUrl:WB+'avaliar-performance', toolMethod:'POST', toolBody:body } }];
}

// === QUIZ: gerar quiz/trivia ===
if (has('quiz','trivia','perguntas sobre','quiz sobre','quiz de')) {
