  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'contar-historia', toolUrl:WB+'contar-historia', toolMethod:'POST', toolBody:body } }];
}

// === COLLAB: proposta de parceria ===
if (has('collab','parceria','proposta de collab','proposta de parceria','colaboracao')) {
  const canal_alvo = text.replace(/^.*?(collab|parceria|colaboracao)\s*(com|para|pro)?\s*/i,'').trim();
  const body = JSON.stringify({meu_canal:'InovareManhwaVerse', canal_alvo: canal_alvo || '', nicho_alvo:'anime/manhwa'});
  return [{ json:{ hasMessage:true, text, chatId, intent:'tool', toolName:'gerar-collab', toolUrl:WB+'gerar-collab', toolMethod:'POST', toolBody:body } }];
