if (has('checklist','pronto pra publicar','revisar publicacao','pre publish','checklist publicacao')) {
  const titulo = text.replace(/^.*?(checklist|pronto|revisar|pre publish)\s*(pra publicar|publicacao|de)?\s*/i,'').trim();
